46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const ALIKE_ITEMS_PER_BLOCK = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	const CURSE_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	const LOYALTY_YEARS_THRESHOLD = 2;
63	const LOYALTY_DISCOUNT_RATE = 0.2;
64	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
65	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
66	
67	const sum = (amounts: number[]): number =>
68	  amounts.reduce((total, amount) => total + amount, 0);
69	
70	const groupByType = (items: Item[]): Item[][] => {
71	  const itemsByType = new Map<string, Item[]>();
72	
73	  for (const item of items) {
74	    const alikeItems = itemsByType.get(item.type);
75	    if (alikeItems) alikeItems.push(item);
76	    else itemsByType.set(item.type, [item]);
77	  }
78	
79	  return [...itemsByType.values()];
80	};
81	
82	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];
83	
84	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
85	  alikeItems.length === ALIKE_ITEMS_PER_BLOCK
86	    ? BLOCK_BASE_PREMIUM
87	    : sum(alikeItems.map(basePremiumOf));
88	
89	const curseSurchargeOf = (item: Item): number =>
90	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
91	
92	const highEnchantmentSurchargeOf = (item: Item): number =>
93	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
94	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
95	    : 0;
96	
97	const itemSurchargesOf = (item: Item): number =>
98	  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);
99	
100	const loyaltyDiscountOf = (customer: Customer, basePremium: number): number =>
101	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
102	
103	const firstInsuranceSurchargeOf = (basePremium: number): number =>
104	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
105	
106	const followUpDiscountOf = (previousQuotes: number, basePremium: number): number =>
107	  previousQuotes > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
108	
109	const quote = (
110	  { items }: QuoteStep,
111	  customer: Customer,
112	  previousQuotes: number,
113	): StepResult => {
114	  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
115	  const itemSurcharges = sum(items.map(itemSurchargesOf));
116	  const loyaltyDiscount = loyaltyDiscountOf(customer, basePremium);
117	  const firstInsuranceSurcharge = firstInsuranceSurchargeOf(basePremium);
118	  const followUpDiscount = followUpDiscountOf(previousQuotes, basePremium);
119	
120	  return {
121	    premium:
122	      basePremium +
123	      itemSurcharges -
124	      loyaltyDiscount +
125	      firstInsuranceSurcharge -
126	      followUpDiscount +
127	      PROCESSING_FEE,
128	  };
129	};
130	
131	export const runScenario = (scenario: Scenario): ScenarioResult => {
132	  const results: StepResult[] = [];
133	  let quotesSoFar = 0;
134	
135	  for (const step of scenario.steps) {
136	    results.push(quote(step as QuoteStep, scenario.customer, quotesSoFar));
137	    quotesSoFar += 1;
138	  }
139	
140	  return { results };
141	};
